package com.inventra.backend.service; import com.inventra.backend.dto.*; import com.inventra.backend.model.*; import com.inventra.backend.repository.*; import org.springframework.stereotype.Service; import java.time.LocalDateTime; import java.util.*; @Service public class OrderService { private final OrderRepository repo; private final ProductRepository products; private final InventoryCoreService inv; private final ReservationRepository reservations; public OrderService(OrderRepository r,ProductRepository p,InventoryCoreService i,ReservationRepository s){repo=r;products=p;inv=i;reservations=s;} public OrderResponse create(OrderRequest r){Order o=new Order();o.setOrderNumber("ORD-"+System.currentTimeMillis());o.setWarehouseId(r.warehouseId());o.setCustomerName(r.customerName());double total=0;List<OrderItem> items=new ArrayList<>();for(OrderItemRequest x:r.items()){Product p=products.findById(x.productId()).orElseThrow(()->new IllegalArgumentException("Product not found: "+x.productId()));items.add(new OrderItem(p.getId(),x.quantity(),p.getPrice()));total+=p.getPrice()*x.quantity();}o.setItems(items);o.setTotalAmount(total);for(OrderItem x:items){var available=inv.get(r.warehouseId(),x.getProductId()).getAvailableQuantity();if(available<x.getQuantity())throw new com.inventra.backend.exception.InsufficientStockException("Insufficient available stock for product "+x.getProductId());}repo.save(o);for(OrderItem x:items){inv.reserve(r.warehouseId(),x.getProductId(),x.getQuantity(),o.getId());StockReservation s=new StockReservation();s.setOrderId(o.getId());s.setWarehouseId(r.warehouseId());s.setProductId(x.getProductId());s.setQuantity(x.getQuantity());reservations.save(s);}o.setStatus(OrderStatus.RESERVED);o.setUpdatedAt(LocalDateTime.now());return map(repo.save(o));} public List<OrderResponse> all(){return repo.findAllByOrderByCreatedAtDesc().stream().map(this::map).toList();} public OrderResponse get(String id){return map(repo.findById(id).orElseThrow(()->new IllegalArgumentException("Order not found")));} public OrderResponse cancel(String id){Order o=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Order not found"));if(o.getStatus()!=OrderStatus.RESERVED&&o.getStatus()!=OrderStatus.CREATED)throw new IllegalStateException("Only reserved orders can be cancelled");for(StockReservation s:reservations.findByOrderIdAndStatus(id,ReservationStatus.ACTIVE)){inv.release(s.getWarehouseId(),s.getProductId(),s.getQuantity(),id);s.setStatus(ReservationStatus.RELEASED);s.setReleasedAt(LocalDateTime.now());reservations.save(s);}o.setStatus(OrderStatus.CANCELLED);o.setUpdatedAt(LocalDateTime.now());return map(repo.save(o));} public OrderResponse fulfill(String id){Order o=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Order not found"));if(o.getStatus()!=OrderStatus.RESERVED)throw new IllegalStateException("Only reserved orders can be fulfilled");for(StockReservation s:reservations.findByOrderIdAndStatus(id,ReservationStatus.ACTIVE)){inv.fulfill(s.getWarehouseId(),s.getProductId(),s.getQuantity(),id);s.setStatus(ReservationStatus.FULFILLED);reservations.save(s);}o.setStatus(OrderStatus.FULFILLED);o.setUpdatedAt(LocalDateTime.now());return map(repo.save(o));} private OrderResponse map(Order o){return new OrderResponse(o.getId(),o.getOrderNumber(),o.getWarehouseId(),o.getCustomerName(),o.getItems(),o.getStatus(),o.getTotalAmount(),o.getCreatedAt());} }
